create or replace function public.check_scholarship_eligibility(p_opportunity_id uuid) returns jsonb language plpgsql stable set search_path to '' as $$ declare v_uid uuid:=(select auth.uid()); v_p public.profiles; v_s public.scholarship_details; v_o public.opportunities; v_score int:=0; v_checks jsonb:='[]'::jsonb; v_field_ok boolean:=true; v_gpa_ok boolean:=true; begin if v_uid is null then raise exception 'authentication required'; end if; if not private.current_user_is_premium() and not private.is_admin_user() then raise exception 'premium subscription required for scholarship eligibility'; end if; select * into v_p from public.profiles where id=v_uid; select * into v_o from public.opportunities where id=p_opportunity_id; if not found or v_o.opportunity_type<>'scholarships'::public.opportunity_type then raise exception 'scholarship opportunity not found'; end if; select * into v_s from public.scholarship_details where opportunity_id=p_opportunity_id; if not found then return jsonb_build_object('score',0,'eligible',false,'checks',jsonb_build_array(jsonb_build_object('check','details','passed',false,'reason','Scholarship eligibility details are not available yet'))); end if; if v_s.minimum_gpa is null then v_gpa_ok:=true; v_score:=v_score+40; elsif v_p.gpa is not null and v_p.gpa>=v_s.minimum_gpa then v_gpa_ok:=true; v_score:=v_score+40; else v_gpa_ok:=false; end if; v_checks:=v_checks||jsonb_build_array(jsonb_build_object('check','minimum_gpa','passed',v_gpa_ok,'required',v_s.minimum_gpa,'current',v_p.gpa)); if coalesce(array_length(v_s.fields_of_study,1),0)=0 then v_field_ok:=true; v_score:=v_score+35; elsif v_p.major is not null and exists(select 1 from unnest(v_s.fields_of_study) f where lower(f)=lower(v_p.major) or lower(v_p.major) like '%'||lower(f)||'%' or lower(f) like '%'||lower(v_p.major)||'%') then v_field_ok:=true; v_score:=v_score+35; else v_field_ok:=false; end if; v_checks:=v_checks||jsonb_build_array(jsonb_build_object('check','field_of_study','passed',v_field_ok,'required',to_jsonb(v_s.fields_of_study),'current',v_p.major)); if v_p.university is not null or v_p.school_name is not null then v_score:=v_score+15; end if; if exists(select 1 from public.profile_documents d where d.user_id=v_uid) then v_score:=v_score+10; end if; return jsonb_build_object('opportunity_id',p_opportunity_id,'score',least(v_score,100),'eligible',v_gpa_ok and v_field_ok,'checks',v_checks,'deadline',v_o.deadline,'institution',v_s.institution,'study_country',v_s.study_country,'funding_type',v_s.funding_type); end; $$;
;
